#!/bin/zsh
# One-shot: execute Sepolia Config proposal #1 (120s/120s) after its grace ends, then submit, vote and execute the restore to 6h/6h.
set -u
cd ~/srv/zero-one-dao
LOG=evidence/testnet/governance-restore-6h-2026-09-08.log
G="npx tsx scripts/testnet-governance.ts"
target=1788867100  # 2026-09-08T11:31:40Z, graceEnds + 6s
while [ $(date +%s) -lt $target ]; do sleep 30; done
echo "== $(date -u) execute #1" >> $LOG
for i in 1 2 3 4 5; do $G --execute 1 --data  >> $LOG 2>&1 && break; sleep 30; done
echo "== $(date -u) submit restore 21600/21600" >> $LOG
$G --voting 21600 --grace 21600 >> $LOG 2>&1 || { echo "submit failed" >> $LOG; exit 1; }
ID=$(grep -o '"id": *"\?[0-9]*' $LOG | tail -1 | grep -o '[0-9]*$')
RDATA=$(grep -o 'executeCommand": "[^"]*' $LOG | tail -1 | sed 's/.*--data //')
echo "restore proposal id=$ID" >> $LOG
sleep 270
echo "== $(date -u) execute restore #$ID" >> $LOG
for i in 1 2 3 4 5 6; do $G --execute $ID --data $RDATA >> $LOG 2>&1 && break; sleep 30; done
$G --status $ID >> $LOG 2>&1
echo "== $(date -u) done" >> $LOG
